#!/usr/bin/env bash
#
# Documentation Post-render Script
# Removes the transient files generated by pre-render.sh, then builds the live
# demo sites on a full render. A single-file render or a preview save leaves the
# demos alone; DEMOS=0 skips them.
# quarto preview never does a full render, so its demo links stay empty until
# you run ./docs/_scripts/build-demos.sh _site once.
#
# @license MIT License
# @copyright 2026 Mickaël Canouil
# @author Mickaël Canouil
#

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
DOCS_DIR="$(dirname "${SCRIPT_DIR}")"

rm -f "${DOCS_DIR}/changelog.qmd" "${DOCS_DIR}/_variables.yml" \
	"${DOCS_DIR}/_atelier-version.yml"
printf '[post-render] Removed changelog.qmd, _variables.yml, and _atelier-version.yml\n'

if [[ -n "${QUARTO_PROJECT_RENDER_ALL:-}" && "${DEMOS:-}" != "0" ]]; then
	"${SCRIPT_DIR}/build-demos.sh" "${QUARTO_PROJECT_OUTPUT_DIR}"
fi
